from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session
from typing import   # ← BUG: List removed

from backend.database import get_db
from backend.models.order import Order
from backend.models.enums import OrderStatus
from backend.schemas.order import (
    OrderCreate,
    OrderResponse,
    OrderUpdateStatus,
)
from backend.services.order_service import create_order_with_items

router = APIRouter(prefix="/orders", tags=["Orders"])


@router.post("/", response_model=OrderResponse, status_code=status.HTTP_201_CREATED)
def create_order(order_in: OrderCreate, db: Session = Depends(get_db)):
    """
    Create a new order with its items.
    """
    try:
        db_order = create_order_with_items(db, order_in)
        return db_order
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/", response_model=List[OrderResponse])
def list_orders(skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):
    """
    Retrieve all orders.
    """
    orders = db.query(Order).offset(skip).limit(limit).all()
    return orders


@router.get("/{order_id}", response_model=OrderResponse)
def get_order(order_id: str, db: Session = Depends(get_db)):
    """
    Retrieve a specific order by ID.
    """
    db_order = db.query(Order).filter(Order.id == order_id).first()
    if db_order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    return db_order


@router.patch("/{order_id}/status", response_model=OrderResponse)
def update_order_status(
    order_id: str, status_update: OrderUpdateStatus, db: Session = Depends(get_db)
):
    """
    Update the status of an order. Validates state transitions.
    """
    db_order = db.query(Order).filter(Order.id == order_id).first()
    if db_order is None:
        raise HTTPException(status_code=404, detail="Order not found")

    current_status = OrderStatus(db_order.status)
    new_status_str = status_update.status
    
    # Validate if new status is a valid enum value
    try:
        new_status = OrderStatus(new_status_str)
    except ValueError:
        raise HTTPException(
            status_code=422, detail=f"Invalid status value: {new_status_str}"
        )

    # Check transition validity
    allowed_next_states = current_status.next_states()
    if new_status.value not in allowed_next_states:
        raise HTTPException(
            status_code=422,
            detail=f"Transition from '{current_status.value}' to '{new_status.value}' is not allowed.",
        )

    db_order.status = new_status.value
    db.commit()
    db.refresh(db_order)

    return db_order


@router.delete("/{order_id}", status_code=status.HTTP_200_OK)
def delete_order(order_id: str, db: Session = Depends(get_db)):
    """
    Delete an order and its associated items.
    """
    db_order = db.query(Order).filter(Order.id == order_id).first()
    if db_order is None:
        raise HTTPException(status_code=404, detail="Order not found")

    db.delete(db_order)
    db.commit()

    return {"detail": "Order deleted successfully"}
